-- how do you let the transaction stay transiently inconsistent?

function makeStore(){
  const seen = [];
  return {
    tryInsert(email){
      if (seen.includes(email)) return false; // reject duplicate
      seen.push(email);
      return true;
    },
    count(){ return seen.length; }
  };
}

